command:
set -euo pipefail
export PATH=/opt/conda/bin:$PATH
export TMPDIR=/tmp HOME=/tmp
cd /tmp

echo "== build an LD-structured fixture: 8 founders, mosaic haplotypes =="
cat > gen.awk <<'AWKEOF'
BEGIN{
  srand(42);
  M=400; K=8; NR_REF=150; NT=20; SWITCH=0.01; MASKEVERY=5;
  for(k=1;k<=K;k++) for(m=1;m<=M;m++) F[k,m]=(rand()<0.35)?1:0;   # founder haplotypes
  # header
  hdr="##fileformat=VCFv4.2\n##contig=<ID=1,length=500000>\n##FORMAT=<ID=GT,Number=1,Type=String,Description=\"Genotype\">";
  print hdr > "ref.vcf"; print hdr > "target.vcf";
  line="#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT";
  rl=line; for(s=1;s<=NR_REF;s++) rl=rl "\tR" s; print rl > "ref.vcf";
  tl=line; for(s=1;s<=NT;s++) tl=tl "\tT" s; print tl > "target.vcf";
  # mosaic haplotypes: walk founders, switching occasionally -> LD blocks
  for(s=1;s<=NR_REF;s++) for(h=1;h<=2;h++){ f=int(rand()*K)+1;
    for(m=1;m<=M;m++){ if(rand()<SWITCH) f=int(rand()*K)+1; RH[s,h,m]=F[f,m]; } }
  for(s=1;s<=NT;s++) for(h=1;h<=2;h++){ f=int(rand()*K)+1;
    for(m=1;m<=M;m++){ if(rand()<SWITCH) f=int(rand()*K)+1; TH[s,h,m]=F[f,m]; } }
  nmask=0;
  for(m=1;m<=M;m++){
    pos=m*1000; id="snp" m;
    r=sprintf("1\t%d\t%s\tA\tG\t.\tPASS\t.\tGT",pos,id);
    for(s=1;s<=NR_REF;s++) r=r sprintf("\t%d|%d",RH[s,1,m],RH[s,2,m]);
    print r > "ref.vcf";
    t=sprintf("1\t%d\t%s\tA\tG\t.\tPASS\t.\tGT",pos,id);
    masked=(m%MASKEVERY==0);
    for(s=1;s<=NT;s++){
      g=TH[s,1,m]+TH[s,2,m];
      if(masked){ t=t "\t./."; printf "%s\tT%d\t%d\n", id, s, g > "truth.txt"; nmask++ }
      else { t=t sprintf("\t%d/%d",TH[s,1,m],TH[s,2,m]) }
    }
    print t > "target.vcf";
  }
  printf "snps %d ref_samples %d target_samples %d masked_genotypes %d\n", M, NR_REF, NT, nmask;
}
AWKEOF
awk -f gen.awk

echo "== minimac4 needs a bgzipped+tabixed target and an msav reference =="
bgzip -f -c target.vcf > target.vcf.gz
tabix -f -p vcf target.vcf.gz
minimac4 --compress-reference ref.vcf -o ref.msav > compress.log 2>&1
minimac4 ref.msav target.vcf.gz -o mm4.vcf.gz -f GT --threads 2 > mm4.log 2>&1
gunzip -f -c mm4.vcf.gz > mm4.vcf
awk 'BEGIN{n=0} /^1\t/{n++} END{print "minimac4_sites", n}' mm4.vcf
minimac4 --version > mm4ver.txt 2>&1 || true
